struct qstr *qstr_remrange(struct qstr *s, size_t start, size_t stop) {
    if (!s || start > stop || stop > s->length) {
        return NULL;
    }
    size_t n_removed = stop - start;
    size_t n_tomove = s->length - stop + 1;
    memmove(s->data + start, s->data + stop, n_tomove);
    s->length -= n_removed;
    return s;
}

#include <stdio.h>

#include "qstr.h"

// Prints every byte of the array (all capacity of them), '\0' as \0.
void dump(const struct qstr *s) {
    printf("length %zu: ", s->length);
    for (size_t i = 0; i < s->capacity; i++) {
        if (s->data[i] == '\0') {
            printf("[\\0]");
        } else {
            printf("[%c]", s->data[i]);
        }
    }
    printf("\n");
}

int main(void) {
    struct qstr *s = qstr_fromcstr("ABCDEFGH");
    if (!s) {
        return 1;
    }
    dump(s);
    qstr_remrange(s, 4, 7);       // remove "EFG" (indexes 4, 5, 6)
    dump(s);
    printf("%s\n", s->data);

    if (qstr_remrange(s, 3, 9) == NULL) {
        printf("3, 9: invalid, nothing removed\n");
    }
    qstr_remrange(s, 2, 2);       // empty range: removes nothing
    qstr_remrange(s, 0, 1);       // remove the first character
    dump(s);
    printf("%s\n", s->data);

    qstr_destroy(s);
    return 0;
}

struct qstr *qstr_ensure_capacity(struct qstr *s, size_t capacity) {
    if (s->capacity >= capacity) {
        return s;
    }
    char *buf = realloc(s->data, capacity);
    if (!buf) {
        fprintf(stderr, "qstr->data reallocation error\n");
        return NULL;
    }
    s->data = buf;
    s->capacity = capacity;
    return s;
}

struct qstr *qstr_assign(struct qstr *lhs, const struct qstr *rhs) {
    if (lhs == rhs) {                                   // 1
        return lhs;
    }
    const size_t REQ_CAPACITY = rhs->length + 1;        // 2
    qstr_ensure_capacity(lhs, REQ_CAPACITY);

    // bug, qstr can contain \0
    // strcpy(lhs->data, rhs->data);
    memcpy(lhs->data, rhs->data, rhs->length + 1);      // 3
    lhs->length = rhs->length;
    return lhs;
}

struct qstr *qstr_assign(struct qstr *lhs, const struct qstr *rhs) {
    if (!lhs) {
        return NULL;
    }
    if (!rhs || lhs == rhs) {
        return lhs;
    }
    const size_t REQ_CAPACITY = rhs->length + 1;
    struct qstr *tmp = qstr_ensure_capacity(lhs, REQ_CAPACITY);
    if (!tmp) {
        return NULL;
    }
    memcpy(lhs->data, rhs->data, rhs->length + 1);
    lhs->length = rhs->length;
    return lhs;
}

struct qstr *qstr_copy(const struct qstr *s) {
    if (!s) {
        return qstr_new();
    }
    struct qstr *q = qstr_alloc(s->capacity);
    if (q) {
        qstr_assign(q, s);
    }
    return q;
}

struct qstr *qstr_concat(struct qstr *lhs, const struct qstr *rhs) {
    if (!lhs) {
        return NULL;
    }
    if (!rhs) {
        return lhs;
    }
    const size_t REQ_CAPACITY = lhs->length + rhs->length + 1;
    struct qstr *tmp = qstr_ensure_capacity(lhs, REQ_CAPACITY);
    if (!tmp) {
        return NULL;
    }
    memmove(lhs->data + lhs->length, rhs->data, rhs->length + 1);
    lhs->length = lhs->length + rhs->length;
    return lhs;
}

#include <stdio.h>

#include "qstr.h"

void show(const char *name, const struct qstr *q) {
    printf("%-3s length %2zu, capacity %2zu: \"%s\"\n",
           name, q->length, q->capacity, q->data);
}

int main(void) {
    struct qstr *a = qstr_fromcstr("CISC");
    struct qstr *b = qstr_fromcstr("220");
    struct qstr *c = qstr_new();
    if (!a || !b || !c) {
        qstr_destroy(a);
        qstr_destroy(b);
        qstr_destroy(c);
        return 1;
    }
    show("a", a);
    show("b", b);

    qstr_concat(a, b);      // needs 4 + 3 + 1 = 8 > 5: grows
    show("a", a);
    qstr_concat(a, a);      // a onto itself: needs 7 + 7 + 1 = 15
    show("a", a);

    qstr_assign(b, a);      // b needs 14 + 1 = 15 > 4: grows
    show("b", b);
    qstr_assign(a, c);      // a becomes "" but keeps capacity 15
    show("a", a);

    qstr_destroy(a);
    qstr_destroy(b);
    qstr_destroy(c);
    return 0;
}

