// in qstr.h
struct qstr;          // declared, not defined: an opaque type

// Returns the length of s (0 if s is NULL).
size_t qstr_length(const struct qstr *s);

// Returns a pointer to the first character of s (NULL if s is NULL).
char *qstr_data(const struct qstr *s);

// in qstr.c
size_t qstr_length(const struct qstr *s) {
    return s ? s->length : 0;
}

char *qstr_data(const struct qstr *s) {
    return s ? s->data : NULL;
}

// last_char2.c: the same job through the opaque interface

#include <stdio.h>

#include "qstr.h"

int main(void) {
    struct qstr *str = qstr_fromcstr("HELLO");
    if (!str) {
        return 1;
    }
    qstr_set(str, qstr_length(str) - 1, 'o');
    puts(qstr_data(str));
    printf("length %zu\n", qstr_length(str));
    qstr_destroy(str);
    return 0;
}

// Copies the length and characters of rhs into lhs, growing lhs if needed.
// Returns lhs. lhs is unchanged if rhs is NULL.
// Returns NULL if lhs is NULL or if memory runs out.
struct qstr *qstr_assign(struct qstr *lhs, const struct qstr *rhs);

// Appends the characters of rhs (which may be lhs itself) to the end of
// lhs, growing lhs if needed. Returns lhs. lhs is unchanged if rhs is NULL.
// Returns NULL if lhs is NULL or if memory runs out.
struct qstr *qstr_concat(struct qstr *lhs, const struct qstr *rhs);

// Removes the characters at indexes start, start + 1, ..., stop - 1.
// Needs 0 <= start <= stop <= s->length. Returns s.
// Returns NULL (and changes nothing) if s is NULL or the range is invalid.
struct qstr *qstr_remrange(struct qstr *s, size_t start, size_t stop);

#include <ctype.h>
#include <stdio.h>
#include <string.h>

#include "qstr.h"

void print(const char *pre, const struct qstr *q) {
    if (pre) {
        printf("%s : length = %zu, capacity = %zu, data = %s\n",
                pre, q->length, q->capacity, q->data);
    }
    else  {
        printf("length = %zu, capacity = %zu, data = %s\n",
                q->length, q->capacity, q->data);
    }
}

int main(void) {
    struct qstr *q = qstr_new();
    print("q", q);
    qstr_destroy(q);

    q = qstr_fromcstr("CISC220");
    print("q", q);

    struct qstr *q2 = qstr_copy(q);
    print("q", q);
    print("q2", q2);

    qstr_clear(q2);
    print("q", q);
    print("q2", q2);

    for (size_t i = 0; i < q->length; i++) {
        char *c = qstr_get(q, i);
        printf("char : %c\n", *c);
    }
    print("q", q);

    for (size_t i = 0; i < q->length; i++) {
        char *c = qstr_set(q, i, tolower(*qstr_get(q, i)));
        printf("char : %c\n", *c);
    }
    print("q", q);

    qstr_assign(q2, q);
    print("q", q);
    print("q2", q2);

    for (size_t i = 0; i < q->length; i++) {
        qstr_set(q, i, toupper(*qstr_get(q, i)));
    }
    print("q", q);
    print("q2", q2);

    qstr_concat(q2, q);
    print("q", q);
    print("q2", q2);

    qstr_concat(q2, q2);
    print("q2", q2);

    struct qstr *q3 = qstr_copy(q);
    for (size_t i = 0; i <= q->length; i++) {
        qstr_assign(q3, q);
        qstr_remrange(q3, i, q3->length);
        print("q3", q3);
    }

    qstr_destroy(q);
    qstr_destroy(q2);
    qstr_destroy(q3);

    return 0;
}

