// add to qstr.c, after qstr_ensure_capacity (and the declaration to qstr.h)

// Inserts the C string cs into s so that its first character ends up at
// index index (0 <= index <= s->length; index == s->length appends).
// cs must not point into s->data. Returns s, or NULL (s unchanged) if
// s or cs is NULL, index is invalid, or memory runs out.
struct qstr *qstr_insert(struct qstr *s, size_t index, const char *cs) {
    if (!s || !cs || index > s->length) {
        return NULL;
    }
    size_t n = strlen(cs);
    if (!qstr_ensure_capacity(s, s->length + n + 1)) {
        return NULL;
    }
    // shift the tail (from index up to and including the '\0') right by n
    memmove(s->data + index + n, s->data + index, s->length - index + 1);
    // copy the new characters into the gap (no '\0' from cs)
    memcpy(s->data + index, cs, n);
    s->length += n;
    return s;
}

